/// <summary>
/// This class implements the Catch Weight On Hand report service
/// </summary>
public class METCatchWeightOnHandService
{ 

}

Method.Source:
/// <summary>
/// Collect error
/// </summary>
/// <returns>String</returns>
private str getErrorStr()
{
    SysInfologEnumerator enumerator;
    SysInfologMessageStruct msgStruct;
    Exception exception;
    str error;
    enumerator = SysInfologEnumerator::newData(infolog.cut());
    while (enumerator.moveNext())
    {
        msgStruct = new SysInfologMessageStruct(enumerator.currentMessage());
        exception = enumerator.currentException();
        error = strfmt("%1 %2", error, msgStruct.message());
    }

    return error;
}

/// <summary>
/// This method calls the InventOnHand report for storage
/// </summary>
/// <param name = "_request">String</param>
/// <returns>String</returns>
public METCatchWeightOnHandResponse callInventOnHandReportStorage(METCatchWeightOnHandRequest _request)
{
    METCatchWeightOnHandResponse response;
    ExecutionNameInventOnhand executionName;
    METProcessingStatus result;
    Description255      message;
    response = new METCatchWeightOnHandResponse();

    try
    {
        ttsbegin;
        changecompany(_request.parmDataAreaId())
        {
            executionName = _request.parmCatchWeightOnHandContract().parmExecutionName();

            if (this.validateExecutionName(executionName))
            {
                //Build the query
                Query query = new Query(queryStr(InventOnhand));
                QueryBuildDataSource qbds = query.dataSourceTable(tableNum(InventDim));
                QueryBuildRange qbrWH  = qbds.addRange(fieldNum(InventDim, InventLocationId));
                QueryBuildRange qbrSite  = qbds.addRange(fieldNum(InventDim, InventSiteId));

                qbrWH.value(this.getWarehouse(executionName));
                qbrSite.value(this.getSite(executionName));

                // Create Args object
                Args args = new Args();
                args.name(menuItemActionStr(InventOnhandStorage)); 
                args.caller(this); 
                InventOnhandStorageController controller = InventOnhandStorageController::construct(args);
                InventOnhandStorageContract contract    = controller ? controller.getDataContractObject() : null;

                if (!contract)
                {
                    throw error(Error::wrongUseOfFunction(funcName()));
                }
                controller.parmInBatch(true);
                controller.parmExecutionMode(SysOperationExecutionMode::ScheduledBatch);
                contract.parmViewInventSiteId(true); 
                contract.parmViewInventLocationId(true); 
                contract.parmQueryString(SysOperationHelper::base64Encode(query.pack()));
                contract.parmExecutionName(executionName);
                controller.parmShowDialog(false);
                controller.parmLoadFromSysLastValue(false);
                controller.batchInfo().parmCaption("@SYS97724");
                controller.startOperation();

                result = METProcessingStatus::Success;
                message = "@MET:InventOnHandReportStorageScheduled";
            }
            else
            {
                result = METProcessingStatus::Error;
                message = "@MET:InvalidExecutionNameFormat";
            }
        }
        ttscommit;
    }
    catch(Exception::CLRError)
    {
        System.Exception interopException = CLRInterop::getLastException();

        result = METProcessingStatus::Error;

        if (interopException)
        {
            message = interopException.ToString();
        }
        else
        {
            message = this.getErrorStr();
        }
        if (!executionName)
        {
            executionName = _request.parmCatchWeightOnHandContract().parmExecutionName();
        }
    }
    catch
    {
        System.Exception interopException = CLRInterop::getLastException();

        result = METProcessingStatus::Error;

        if (interopException)
        {
            message = interopException.ToString();
        }
        else
        {
            message = this.getErrorStr();
        }
        if (!executionName)
        {
            executionName = _request.parmCatchWeightOnHandContract().parmExecutionName();
        }
    }        
    //return response;
    return METCatchWeightOnHandResponse::newFromParameters(result, message, executionName);
}

/// <summary>
/// This method validates the execution name format
/// </summary>
/// <param name = "_executionName">String</param>
/// <returns>String</returns>
public boolean validateExecutionName(str _executionName)
{
    boolean isValid = false;        
    int underscorePos;
    str warehouse;
    str site;

    if (!_executionName)
    {
        return false;
    }

    // Expect format "warehouse_site"
    underscorePos = strFind(_executionName, "_", 1, strLen(_executionName));
    if (underscorePos <= 0)
    {
        return false;
    }

    warehouse = subStr(_executionName, 1, underscorePos - 1);
    site      = subStr(_executionName, underscorePos + 1, strLen(_executionName) - underscorePos);

    // Basic sanity
    if (!warehouse || !site)
    {
        return false;
    }

    // Ensure the location belongs to the site
    if (InventLocation::find(warehouse) && InventSite::find(site))
    {
        isValid = true;
    }

    return isValid;
}

/// <summary>
/// This method extracts the site from the execution name
/// </summary>
/// <param name = "_executionName">String</param>
/// <returns>String</returns>
public str getSite(str _executionName)
{
    boolean isValid = false;
    int underscorePos;
    str site;

    if (!_executionName)
    {
        return site;
    }

    // Expect format "warehouse_site"
    underscorePos = strFind(_executionName, "_", 1, strLen(_executionName));
    if (underscorePos <= 0)
    {
        return site;
    }


    site      = subStr(_executionName, underscorePos + 1, strLen(_executionName) - underscorePos);

    return site;
}

/// <summary>
/// This method extracts the warehouse from the execution name
/// </summary>
/// <param name = "_executionName">String</param>
/// <returns>String</returns>
public str getWarehouse(str _executionName)
{
    boolean isValid = false;
    int underscorePos;
    str warehouse;       

    if (!_executionName)
    {
        return warehouse;
    }

    // Expect format "warehouse_site"
    underscorePos = strFind(_executionName, "_", 1, strLen(_executionName));
    if (underscorePos <= 0)
    {
        return warehouse;
    }

    warehouse = subStr(_executionName, 1, underscorePos - 1);

    return warehouse;
}
